 * Create or update a folder/file IPNS entry.
 * Handles both folder metadata and per-file metadata IPNS records.
 */
private async upsertFolderIpns(
  userId: string,
  ipnsName: string,
  metadataCid: string,
  encryptedIpnsPrivateKey?: string,
  keyEpoch?: number,
  recordType: 'folder' | 'file' = 'folder',

