    republishEntriesProcessed: { inc: jest.Mock };
    republishBatchDuration: { startTimer: jest.Mock };
  };

  function createMockJob(overrides: Partial<Job> = {}): Job {
    return {
      name: 'republish-batch',
      id: 'job-1',
